elegant.text:
import QtQuick
import Ljos.Core
import Ljos.Blocks

// ljos.dev's own shell, and every page's as the build writes it: a
// header with the name, where to go, search and the reader's choices,
// the page under it as wide as a front page wants, and, on the docs,
// their sidebar and what is on the page beside it. Narrow, a phone's,
// the header is the name and one menu button, and the menu holds the
// rest.
//
// Nothing here is the site's: each part is a place (a Slot) the site
// puts its pieces in by name, `site.page` the page itself. So this file
// is one anyone may rewrite, in the page, and the site stands in what
// they make (Site/ShellSource.qml). `site` is the site's state: its
// router, the reader's preferences and the look.
Rectangle {
    id: shell
    objectName: "elegantShell"

    property var site: null
    readonly property var router: site ? site.router : null
    readonly property bool wide: site ? site.preferences.wide : width >= 1000
    readonly property bool calm: site ? site.preferences.calm : false
    readonly property bool docs: router !== null && router.docsRoute
    readonly property bool sidebarShown: wide && docs
    // With the Observer docked over the right, what is on the page goes,
    // so the app the reader clicks in keeps the room beside it.
    readonly property bool tocShown: sidebarShown && width >= 1200 && router.headings.length > 0 && !(site && site.docked > 0)
    readonly property int gutter: wide ? 32 : 20
    readonly property bool menuOpen: site ? site.menuOpen && !wide : false
    // A page other than the docs is this wide at most here: a front page
    // has the room to span.
    readonly property int pageWidest: 1280
    // The header's row stands over the page's grid, so the name lines up
    // with the page's first column and the reader's choices with its
    // last; on the docs, whose sidebar meets the window's edge, and on a
    // phone it keeps to the gutter.
    readonly property int inset: docs || !wide ? gutter : Math.max(gutter, Math.round((width - pageWidest) / 2))

    // The colours the site draws in, for this shell's own lines: none of
    // its own before it is given the site.
    QtObject {
        id: look
        readonly property color canvas: shell.site ? shell.site.theme.canvas : "transparent"
        readonly property color divider: shell.site ? shell.site.theme.divider : "transparent"
    }

    width: parent ? parent.width : 1440
    height: parent ? parent.height : 900
    color: look.canvas

    // The header. Each part of the shell is a landmark, so a reader goes
    // to the page, the docs or the menu as a sighted one looks.
    Rectangle {
        id: header
        z: 3
        width: parent.width
        height: 64
        color: look.canvas
        Accessible.role: Accessible.Section
        Accessible.name: "Ljós"

        Rectangle {
            y: parent.height - 1
            width: parent.width
            height: 1
            color: look.divider
        }
        // The brand and the sections, each on the header's middle line:
        // the row is the header's height so each part centres on it,
        // whatever height the other has.
        Row {
            x: shell.inset
            height: header.height
            spacing: 32

            Row {
                y: Math.round((header.height - height) / 2)
                Slot { name: "site.brand" }
            }
            Row {
                visible: shell.wide
                y: Math.round((header.height - height) / 2)
                Slot { name: "site.nav" }
            }
        }
        Row {
            x: parent.width - width - (shell.wide ? shell.inset : shell.gutter - 8)
            anchors.verticalCenter: parent.verticalCenter
            spacing: 12

            Item {
                visible: shell.wide
                width: 280
                height: 40
                Slot { name: "site.search" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.github" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.switcher" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.preferences" }
            }
            // A phone's one control: the menu.
            Row {
                visible: !shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.menu" }
            }
        }
    }

    // The docs, beside the page.
    Item {
        id: sidebar
        visible: shell.sidebarShown
        y: header.height
        width: 264
        height: parent.height - y
        // Made where it shows: a narrow page would carry the docs' whole
        // list, hidden, in its first load.
        Loader {
            anchors.fill: parent
            active: shell.sidebarShown
            sourceComponent: Component {
                Item {
                    Slot { name: "site.sidebar" }
                }
            }
        }
    }
    Rectangle {
        visible: shell.sidebarShown
        x: sidebar.width
        y: header.height
        width: 1
        height: parent.height - y
        color: look.divider
    }

    // The page itself, the footer under it.
    Item {
        id: page
        x: shell.sidebarShown ? sidebar.width + 1 : 0
        y: header.height
        width: parent.width - x - (shell.tocShown ? toc.width : 0)
        height: parent.height - y
        Slot { name: "site.page" }
    }

    // On this page, beside it where there is room.
    Item {
        id: toc
        visible: shell.tocShown
        x: parent.width - width
        y: header.height
        width: 224
        height: parent.height - y
        Slot { name: "site.toc" }
    }

    // A phone's menu: search, where to go, the reader's choices, what is
    // on this page and the docs. It rises into place, or with reduced
    // motion only fades.
    Rectangle {
        id: menu
        z: 2
        Accessible.role: Accessible.Section
        Accessible.name: t`Menu`
        width: parent.width
        y: header.height + (shell.menuOpen || shell.calm ? 0 : -16)
        height: parent.height - header.height
        visible: !shell.wide && (shell.menuOpen || opacity > 0)
        opacity: shell.menuOpen ? 1 : 0
        color: look.canvas
        Behavior on opacity {
            NumberAnimation {
                duration: shell.menuOpen ? 250 : 100
                easing.type: Easing.OutCubic
            }
        }
        Behavior on y {
            NumberAnimation {
                duration: shell.menuOpen ? 250 : 100
                easing.type: Easing.OutCubic
            }
        }

        // What it holds is made when it opens and let go once it has
        // faded: closed, it is the docs' whole list again in every
        // page's first load, which a reader on a wide window never sees.
        Loader {
            anchors.fill: parent
            active: shell.menuOpen || menu.opacity > 0
            sourceComponent: Component {
                Flickable {
                    anchors.fill: parent
                    contentWidth: width
                    contentHeight: menuColumn.implicitHeight + 48
                    clip: true

                    Column {
                        id: menuColumn
                        x: shell.gutter
                        y: 24
                        width: parent.width - 2 * shell.gutter
                        spacing: 24

                        Item {
                            z: 2
                            width: parent.width
                            height: 44
                            Slot { name: "site.search" }
                        }
                        Column {
                            width: parent.width
                            Slot { name: "site.nav.large" }
                        }
                        Row {
                            spacing: 8
                            Slot { name: "site.github" }
                            Slot { name: "site.preferences" }
                        }
                        Row {
                            Slot { name: "site.switcher" }
                        }
                        Column {
                            visible: shell.docs
                            width: parent.width
                            Slot { name: "site.toc.inline" }
                        }
                        Rectangle {
                            width: parent.width
                            height: 1
                            color: look.divider
                        }
                        Column {
                            width: parent.width
                            Slot { name: "site.docs.inline" }
                        }
                    }
                }
            }
        }
    }
}

cyberpunk.text:
import QtQuick
import Ljos.Core
import Ljos.Blocks

// A console for the running site: a rail along the top reads out what
// the page is doing as it does it (where the reader is, the time, how
// many objects are alive, the frame rate while something moves, and
// what draws), a rail down the left is where to go, numbered as a
// console's channels, and the page stands in the rest, on a canvas of
// still scanlines. On a phone the top is the name and one menu button,
// and the readings move to a bar along the bottom.
//
// Like every shell here, nothing in it is the site's: each part is a
// place (a Slot) the site puts its pieces in by name, and `site` is the
// site's state, so the file is one a reader may rewrite in the page.
Rectangle {
    id: shell
    objectName: "cyberpunkShell"

    property var site: null
    readonly property var router: site ? site.router : null
    readonly property bool wide: site ? site.preferences.wide : width >= 1000
    readonly property bool calm: site ? site.preferences.calm : false
    readonly property string route: router ? router.route : "/"
    readonly property bool docs: router !== null && router.docsRoute
    readonly property bool sidebarShown: wide && docs
    readonly property bool tocShown: sidebarShown && width >= 1520 && router.headings.length > 0 && !(site && site.docked > 0)
    readonly property bool menuOpen: site ? site.menuOpen && !wide : false
    readonly property int pageWidest: 1280
    readonly property int gutter: wide ? 24 : 16
    readonly property int railWidth: 200
    readonly property int hudHeight: 48
    readonly property int barHeight: 56

    // The page on how a shell is written: its channel of the rail.
    readonly property string shellsRoute: "/start/your-own-shell/"
    readonly property string metricsRoute: "/benchmarks/"
    // Where to go, each a channel. The benchmarks are one only once the
    // site has that page (a route it has no name for is not one).
    readonly property var channels: router === null ? [] : [
        { label: t`Console`, to: "/", current: route === "/" },
        { label: t`Demos`, to: "/demos/", current: router.demosRoute },
        { label: t`Showcase`, to: "/showcase/", current: router.showcaseRoute }
    ].concat(router.nameOf(metricsRoute) !== metricsRoute ? [{ label: t`Metrics`, to: metricsRoute, current: route === metricsRoute }] : []).concat([
        { label: t`Docs`, to: "/start/", current: docs && route !== shellsRoute && route !== metricsRoute },
        { label: t`Shells`, to: shellsRoute, current: route === shellsRoute }
    ])

    // The colours and faces the site draws in: none of its own before it
    // is given the site.
    QtObject {
        id: look
        readonly property var theme: shell.site ? shell.site.theme : null
        readonly property bool dark: theme ? theme.dark : true
        readonly property color canvas: theme ? theme.canvas : "transparent"
        readonly property color surface: theme ? theme.surface : "transparent"
        readonly property color hover: theme ? theme.surfaceHover : "transparent"
        readonly property color divider: theme ? theme.divider : "transparent"
        readonly property color accent: theme ? theme.accent : "transparent"
        readonly property color accent2: theme ? theme.accent2 : "transparent"
        readonly property color link: theme ? theme.link : "transparent"
        readonly property color text: theme ? theme.text : "transparent"
        readonly property color muted: theme ? theme.textMuted : "transparent"
        readonly property string mono: theme ? theme.mono : "monospace"
        readonly property string sans: theme ? theme.sans : "sans-serif"
    }

    // The readings. The time, to the minute, woken once a minute at its
    // turn; the frame rate, measured only while something moves (the
    // shell coming in, the page scrolling) and kept after, so a page at
    // rest asks for no frames.
    property string clock: ""
    property int fps: 0
    readonly property int alive: site ? site.alive : 0
    readonly property string renderer: site ? site.renderer : ""
    readonly property real offset: site ? site.pageOffset : 0

    function tick() {
        var now = new Date();
        shell.clock = String(now.getHours()).padStart(2, "0") + ":" + String(now.getMinutes()).padStart(2, "0");
        minute.interval = 60000 - now.getSeconds() * 1000 - now.getMilliseconds() + 20;
        minute.restart();
    }
    function sample() {
        frames.running = true;
        settle.restart();
    }
    Timer {
        id: minute
        onTriggered: shell.tick()
    }
    FrameAnimation {
        id: frames
        onTriggered: {
            if (frames.smoothFrameTime > 0)
                shell.fps = Math.round(1 / frames.smoothFrameTime);
        }
    }
    Timer {
        id: settle
        interval: 1200
        onTriggered: frames.running = false
    }
    onOffsetChanged: sample()
    onSiteChanged: if (site) site.measureRenderer()
    Component.onCompleted: {
        tick();
        sample();
        if (site)
            site.measureRenderer();
    }

    width: parent ? parent.width : 1440
    height: parent ? parent.height : 900
    color: look.canvas

    // One reading of the rails: what it is, muted, and its value in the
    // accent, said to a reader as one line.
    component Reading: Item {
        id: reading
        property string label: ""
        property string value: ""
        property string said: ""
        // Stacked, a phone's: the label over its value.
        property bool stacked: false
        implicitWidth: stacked ? Math.max(labelText.implicitWidth, valueText.implicitWidth) : labelText.implicitWidth + 8 + valueText.implicitWidth
        implicitHeight: stacked ? 36 : 20
        Accessible.role: Accessible.StaticText
        Accessible.name: said

        Text {
            id: labelText
            text: reading.label
            color: look.muted
            font.family: look.mono
            font.pixelSize: 12
            lineHeightMode: Text.FixedHeight
            lineHeight: reading.stacked ? 16 : 20
            Accessible.ignored: true
        }
        Text {
            id: valueText
            x: reading.stacked ? 0 : labelText.implicitWidth + 8
            y: reading.stacked ? 18 : 0
            width: reading.stacked ? reading.width : implicitWidth
            text: reading.value
            elide: Text.ElideMiddle
            color: look.link
            font.family: look.mono
            font.pixelSize: 12
            font.weight: Font.DemiBold
            lineHeightMode: Text.FixedHeight
            lineHeight: reading.stacked ? 18 : 20
            Accessible.ignored: true
        }
    }

    // A channel of the rail: its number, its name, and a page's address
    // (an `a` a reader can open in a new tab), or, as `action`, a button
    // that says it was `pressed` (an item is made a link or not as it is
    // written, so this is said as written too). The one the
    // reader is on is lit; under the pointer its edge splits into the
    // second colour and the first, as a misaligned screen's does.
    component Channel: Item {
        id: channel
        property int number: 1
        property string label: ""
        property string to: ""
        property bool current: false
        property bool action: false
        readonly property string href: to !== "" && shell.router ? shell.router.address(to) : ""
        signal pressed

        width: parent ? parent.width : 168
        height: shell.wide ? 40 : 44
        activeFocusOnTab: true
        Accessible.role: action ? Accessible.Button : Accessible.Link
        Accessible.name: label
        Accessible.selected: current
        Accessible.onPressAction: () => channel.press()
        Keys.onPressed: (event) => {
            if (event.key === Qt.Key_Return || event.key === Qt.Key_Enter || event.key === Qt.Key_Space) {
                channel.press();
                event.accepted = true;
            }
        }
        function press() {
            if (action)
                channel.pressed();
            else if (shell.router)
                shell.router.go(to);
        }

        Rectangle {
            x: -1
            width: parent.width
            height: parent.height
            color: "transparent"
            border.color: look.accent2
            border.width: 1
            opacity: area.containsMouse ? 0.9 : 0
            Accessible.ignored: true
        }
        Rectangle {
            x: 1
            width: parent.width
            height: parent.height
            color: "transparent"
            border.color: look.accent
            border.width: 1
            opacity: area.containsMouse ? 0.9 : 0
            Accessible.ignored: true
        }
        Rectangle {
            anchors.fill: parent
            color: channel.current ? look.hover : "transparent"
            border.color: channel.activeFocus ? look.accent : "transparent"
            border.width: 2
            Accessible.ignored: true
        }
        Rectangle {
            visible: channel.current
            width: 2
            height: parent.height
            color: look.accent
            Accessible.ignored: true
        }
        Text {
            x: 14
            anchors.verticalCenter: parent.verticalCenter
            text: String(channel.number).padStart(2, "0")
            color: channel.current ? look.link : look.muted
            font.family: look.mono
            font.pixelSize: 12
            Accessible.ignored: true
        }
        Text {
            x: 44
            anchors.verticalCenter: parent.verticalCenter
            text: channel.label
            color: channel.current ? look.link : look.text
            font.family: look.sans
            font.pixelSize: 15
            font.weight: channel.current ? Font.DemiBold : Font.Normal
            Accessible.ignored: true
        }
        MouseArea {
            id: area
            anchors.fill: parent
            hoverEnabled: true
            cursorShape: Qt.PointingHandCursor
            Accessible.ignored: true
            onClicked: channel.press()
        }
    }

    // The canvas's scanlines: a line every third pixel, still, and under
    // everything, so they stand between the reader and nothing they press.
    Image {
        anchors.fill: parent
        fillMode: Image.Tile
        sourceSize.width: 4
        sourceSize.height: 3
        source: "data:image/svg+xml," + encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' width='4' height='3'><rect y='2' width='4' height='1' fill='" + (look.dark ? "#00f0ff" : "#05060a") + "' fill-opacity='" + (look.dark ? "0.05" : "0.035") + "'/></svg>")
        Accessible.ignored: true
    }

    // The top rail. Each part of the shell is a landmark, so a reader
    // goes to the page, the channels or the readings as a sighted one
    // looks.
    Rectangle {
        id: hud
        z: 3
        width: parent.width
        height: shell.wide ? shell.hudHeight : 56
        color: look.canvas
        Accessible.role: Accessible.Section
        Accessible.name: "Ljós"

        Rectangle {
            y: parent.height - 1
            width: parent.width
            height: 1
            color: look.accent
            opacity: 0.55
        }
        Row {
            x: shell.gutter
            anchors.verticalCenter: parent.verticalCenter
            spacing: 28

            Row {
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.brand" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                spacing: 24

                Reading {
                    label: t`Route`
                    value: shell.route
                    said: t`Route ${shell.route}`
                }
                Reading {
                    visible: shell.width >= 1180
                    label: t`Clock`
                    value: shell.clock
                    said: t`Clock ${shell.clock}`
                }
                Reading {
                    label: t`Objects alive`
                    value: String(shell.alive)
                    said: t`Objects alive ${shell.alive}`
                }
                Reading {
                    label: t`Frame rate`
                    value: shell.fps > 0 ? t`${shell.fps} fps` : "--"
                    said: shell.fps > 0 ? t`Frame rate ${shell.fps} fps` : t`Frame rate not measured yet`
                }
                Reading {
                    visible: shell.width >= 1300 && shell.renderer !== ""
                    label: t`Renderer`
                    value: shell.renderer
                    said: t`Renderer ${shell.renderer}`
                }
            }
        }
        Row {
            x: parent.width - width - (shell.wide ? shell.gutter : shell.gutter - 8)
            anchors.verticalCenter: parent.verticalCenter
            spacing: 12

            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.github" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.switcher" }
            }
            Row {
                visible: shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.preferences" }
            }
            // A phone's one control: the menu.
            Row {
                visible: !shell.wide
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.menu" }
            }
        }
    }

    // The channels, down the left: search over them, the shell's own
    // source under them.
    Rectangle {
        id: rail
        visible: shell.wide
        y: hud.height
        width: shell.railWidth
        height: parent.height - y
        color: look.canvas
        Accessible.role: Accessible.Section
        Accessible.name: t`Sections`

        Rectangle {
            x: parent.width - 1
            width: 1
            height: parent.height
            color: look.divider
        }
        Column {
            x: 16
            y: 16
            width: parent.width - 32
            spacing: 4

            Item {
                z: 2
                width: parent.width
                height: 40
                Slot { name: "site.search" }
            }
            Item {
                width: 1
                height: 16
            }
            Repeater {
                model: shell.channels

                Channel {
                    required property var modelData
                    required property int index
                    number: index + 1
                    label: modelData.label
                    to: modelData.to
                    current: modelData.current
                }
            }
            Item {
                width: 1
                height: 16
            }
            Rectangle {
                width: parent.width
                height: 1
                color: look.divider
            }
            Item {
                width: 1
                height: 12
            }
            Channel {
                number: shell.channels.length + 1
                action: true
                label: t`Source`
                onPressed: if (shell.site) shell.site.showSource("cyberpunk")
            }
        }
    }

    // The docs, beside the channels.
    Item {
        id: sidebar
        visible: shell.sidebarShown
        x: rail.width
        y: hud.height
        width: 264
        height: parent.height - y
        Slot { name: "site.sidebar" }
    }
    Rectangle {
        visible: shell.sidebarShown
        x: sidebar.x + sidebar.width
        y: hud.height
        width: 1
        height: parent.height - y
        color: look.divider
    }

    // The page itself, the footer under it.
    Item {
        id: page
        x: !shell.wide ? 0 : shell.sidebarShown ? sidebar.x + sidebar.width + 1 : rail.width
        y: hud.height
        width: parent.width - x - (shell.tocShown ? toc.width : 0)
        height: parent.height - y - (shell.wide ? 0 : shell.barHeight)
        Slot { name: "site.page" }
    }

    // On this page, beside it where there is room.
    Item {
        id: toc
        visible: shell.tocShown
        x: parent.width - width
        y: hud.height
        width: 224
        height: parent.height - y
        Slot { name: "site.toc" }
    }

    // A phone's readings, along the bottom.
    Rectangle {
        id: bar
        z: 3
        visible: !shell.wide
        y: parent.height - height
        width: parent.width
        height: shell.barHeight
        color: look.canvas
        Accessible.role: Accessible.Section
        Accessible.name: t`Telemetry`

        Rectangle {
            width: parent.width
            height: 1
            color: look.accent
            opacity: 0.55
        }
        Row {
            id: readings
            x: shell.gutter
            anchors.verticalCenter: parent.verticalCenter
            spacing: 12

            Reading {
                stacked: true
                width: Math.max(64, bar.width - 2 * shell.gutter - 3 * readings.spacing - aliveReading.width - fpsReading.width - clockReading.width)
                label: t`Route`
                value: shell.route
                said: t`Route ${shell.route}`
            }
            Reading {
                id: aliveReading
                stacked: true
                width: implicitWidth
                label: t`Objects`
                value: String(shell.alive)
                said: t`Objects alive ${shell.alive}`
            }
            Reading {
                id: fpsReading
                stacked: true
                width: implicitWidth
                label: t`Frame rate`
                value: shell.fps > 0 ? t`${shell.fps} fps` : "--"
                said: shell.fps > 0 ? t`Frame rate ${shell.fps} fps` : t`Frame rate not measured yet`
            }
            Reading {
                id: clockReading
                stacked: true
                width: implicitWidth
                label: t`Clock`
                value: shell.clock
                said: t`Clock ${shell.clock}`
            }
        }
    }

    // A phone's menu: search, where to go, the reader's choices, what is
    // on this page and the docs. It rises into place, or with reduced
    // motion only fades.
    Rectangle {
        id: menu
        z: 2
        Accessible.role: Accessible.Section
        Accessible.name: t`Menu`
        width: parent.width
        y: hud.height + (shell.menuOpen || shell.calm ? 0 : -16)
        height: parent.height - hud.height - shell.barHeight
        visible: !shell.wide && (shell.menuOpen || opacity > 0)
        opacity: shell.menuOpen ? 1 : 0
        color: look.canvas
        Behavior on opacity {
            NumberAnimation {
                duration: shell.menuOpen ? 250 : 100
                easing.type: Easing.OutCubic
            }
        }
        Behavior on y {
            NumberAnimation {
                duration: shell.menuOpen ? 250 : 100
                easing.type: Easing.OutCubic
            }
        }

        Flickable {
            anchors.fill: parent
            contentWidth: width
            contentHeight: menuColumn.implicitHeight + 48
            clip: true

            Column {
                id: menuColumn
                x: shell.gutter
                y: 24
                width: parent.width - 2 * shell.gutter
                spacing: 24

                Item {
                    z: 2
                    width: parent.width
                    height: 44
                    Slot { name: "site.search" }
                }
                Column {
                    width: parent.width
                    spacing: 4
                    Repeater {
                        model: shell.channels

                        Channel {
                            required property var modelData
                            required property int index
                            number: index + 1
                            label: modelData.label
                            to: modelData.to
                            current: modelData.current
                        }
                    }
                }
                Row {
                    spacing: 8
                    Slot { name: "site.github" }
                    Slot { name: "site.preferences" }
                }
                Row {
                    Slot { name: "site.switcher" }
                }
                Column {
                    visible: shell.docs
                    width: parent.width
                    Slot { name: "site.toc.inline" }
                }
                Rectangle {
                    width: parent.width
                    height: 1
                    color: look.divider
                }
                Column {
                    width: parent.width
                    Slot { name: "site.docs.inline" }
                }
            }
        }
    }
}

workbench.text:
import QtQuick
import Ljos.Core
import Ljos.Blocks
import Ljos.Controls as C

// The site as a workbench: every page of it on the left, as files are,
// the page in the middle, and on the right what it is made of: its
// Source.
//
// Its parts are places (Slots) the site puts its pieces in by name, as
// the Elegant shell's are: `site.page` is the very page another shell
// showed, still where the reader was on it.
Rectangle {
    id: shell
    objectName: "workbenchShell"

    property var site: null
    readonly property var router: site ? site.router : null
    // A page other than the docs is this wide at most here.
    readonly property int pageWidest: 960

    QtObject {
        id: look
        readonly property color canvas: shell.site ? shell.site.theme.canvas : C.Theme.canvas
        readonly property color surface: shell.site ? shell.site.theme.surface : C.Theme.surface
        readonly property color divider: shell.site ? shell.site.theme.divider : C.Theme.border
        readonly property color text: shell.site ? shell.site.theme.text : C.Theme.text
        readonly property color textMuted: shell.site ? shell.site.theme.textMuted : C.Theme.textMuted
        readonly property string sans: shell.site ? shell.site.theme.sans : ""
    }

    width: parent ? parent.width : 1440
    height: parent ? parent.height : 900
    color: look.canvas

    // The bar: the name, the page's own, search and the reader's choices.
    Rectangle {
        id: bar
        z: 3
        width: parent.width
        height: 52
        color: look.surface
        Accessible.role: Accessible.Section
        Accessible.name: "Ljós"

        Rectangle {
            y: parent.height - 1
            width: parent.width
            height: 1
            color: look.divider
        }
        Row {
            x: 16
            anchors.verticalCenter: parent.verticalCenter
            spacing: 16

            Row {
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.brand" }
            }
            Rectangle {
                anchors.verticalCenter: parent.verticalCenter
                width: 1
                height: 24
                color: look.divider
            }
            Text {
                anchors.verticalCenter: parent.verticalCenter
                width: Math.max(0, bar.width - 760)
                text: shell.router ? shell.router.title : ""
                color: look.textMuted
                font.family: look.sans
                font.pixelSize: 14
                elide: Text.ElideRight
            }
        }
        Row {
            x: parent.width - width - 12
            anchors.verticalCenter: parent.verticalCenter
            spacing: 8

            Item {
                width: 260
                height: 36
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.search" }
            }
            Row {
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.github" }
            }
            Row {
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.switcher" }
            }
            Row {
                anchors.verticalCenter: parent.verticalCenter
                Slot { name: "site.preferences" }
            }
        }
    }

    // The files: every page of the site.
    Rectangle {
        id: files
        y: bar.height
        width: 264
        height: parent.height - y
        color: look.surface

        Text {
            x: 16
            y: 12
            text: t`Pages`
            color: look.textMuted
            font.family: look.sans
            font.pixelSize: 12
            font.weight: Font.DemiBold
            font.capitalization: Font.AllUppercase
            font.letterSpacing: 0.6
            Accessible.ignored: true
        }
        Item {
            y: 32
            width: parent.width
            height: parent.height - y
            Slot { name: "site.tree" }
        }
    }
    Rectangle {
        x: files.width
        y: bar.height
        width: 1
        height: parent.height - y
        color: look.divider
    }

    // The page.
    Item {
        id: page
        x: files.width + 1
        y: bar.height
        width: panel.x - 1 - x
        height: parent.height - y
        Slot { name: "site.page" }
    }

    // What the page is made of.
    Rectangle {
        x: panel.x - 1
        y: bar.height
        width: 1
        height: parent.height - y
        color: look.divider
    }
    Rectangle {
        id: panel
        x: parent.width - width
        y: bar.height
        width: Math.round(Math.min(460, Math.max(340, shell.width * 0.28)))
        height: parent.height - y
        color: look.surface
        Accessible.role: Accessible.ComplementaryContent
        Accessible.name: t`Inspector`

        Text {
            x: 16
            y: 12
            text: t({ message: "Source", context: "panel" })
            color: look.textMuted
            font.family: look.sans
            font.pixelSize: 12
            font.weight: Font.DemiBold
            font.capitalization: Font.AllUppercase
            font.letterSpacing: 0.6
            Accessible.ignored: true
        }
        Item {
            y: 32
            width: parent.width
            height: parent.height - y
            Slot { name: "site.source" }
        }
    }
}

desktop.text:
import QtQuick
import Ljos.Core
import Ljos.Blocks
import Ljos.Controls as C

// The site as a desktop app: a menu bar whose menus do what they say
// (open a page, change the scheme, the motion and the shell), a toolbar,
// every page in a sidebar, the pages the reader opened as tabs, and a
// status bar with the page, how long the page took to come alive and how
// many objects are alive in it.
//
// Its parts are places (Slots) the site puts its pieces in by name, as
// the Elegant shell's are: `site.page` is the very page another shell
// showed, still where the reader was on it. The tabs are this shell's
// own: which pages are open is how it shows the site, not the site's.
Rectangle {
    id: shell
    objectName: "desktopShell"

    property var site: null
    readonly property var router: site ? site.router : null
    readonly property var preferences: site ? site.preferences : null
    readonly property string route: router ? router.route : "/"
    // A page other than the docs is this wide at most here.
    readonly property int pageWidest: 1040
    // What the status bar says of the page: how long it took to come
    // alive (-1 until it has), and how many objects are alive in it.
    readonly property int hydratedMs: site ? site.hydratedIn : -1
    readonly property int aliveCount: site ? site.alive : 0

    // The pages open, in the order they were opened. Opened as the
    // reader goes, never bound to the route: a binding would make the
    // list the route alone again on every move, and lose the others.
    property var tabs: []
    function opened() {
        if (!shell.router)
            return;
        if (shell.tabs.indexOf(shell.route) < 0)
            shell.tabs = shell.tabs.concat([shell.route]);
        tabBar.currentIndex = shell.tabs.indexOf(shell.route);
    }
    onRouteChanged: shell.opened()
    // Given the site once made, as a shell that comes later is.
    onRouterChanged: shell.opened()
    Component.onCompleted: shell.opened()

    function close(at) {
        if (shell.tabs.length < 2)
            return;
        var open = shell.tabs.slice();
        var gone = open.splice(at, 1)[0];
        shell.tabs = open;
        if (gone === shell.route)
            shell.router.go(open[Math.min(at, open.length - 1)]);
        else
            tabBar.currentIndex = open.indexOf(shell.route);
    }

    QtObject {
        id: look
        readonly property color canvas: shell.site ? shell.site.theme.canvas : C.Theme.canvas
        readonly property color surface: shell.site ? shell.site.theme.surface : C.Theme.surface
        readonly property color divider: shell.site ? shell.site.theme.divider : C.Theme.border
        readonly property color textMuted: shell.site ? shell.site.theme.textMuted : C.Theme.textMuted
        readonly property string sans: shell.site ? shell.site.theme.sans : ""
    }

    width: parent ? parent.width : 1440
    height: parent ? parent.height : 900
    color: look.canvas

    // The header: both bars are one landmark, so a reader finds it by
    // the name it has in every shell.
    Item {
        id: header
        z: 4
        width: parent.width
        height: toolBar.y + toolBar.height
        Accessible.role: Accessible.Section
        Accessible.name: "Ljós"

        // The menu bar.
        Rectangle {
            id: menuBar
            z: 4
            width: parent.width
            height: 36
            color: look.surface

            Row {
                x: 8
                anchors.verticalCenter: parent.verticalCenter
                spacing: 2

                Row {
                    anchors.verticalCenter: parent.verticalCenter
                    Slot { name: "site.brand.small" }
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    text: t`File`
                    onClicked: fileMenu.open()

                    C.Menu {
                        id: fileMenu
                        y: parent.height

                        C.MenuItem {
                            text: t`Open…`
                            iconName: "search"
                            shortcut: "/"
                            onTriggered: shell.site.find()
                        }
                        C.MenuItem {
                            text: t`Close tab`
                            iconName: "x"
                            enabled: shell.tabs.length > 1
                            onTriggered: shell.close(shell.tabs.indexOf(shell.route))
                        }
                    }
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    text: t`View`
                    onClicked: viewMenu.open()

                    C.Menu {
                        id: viewMenu
                        y: parent.height

                        Repeater {
                            model: shell.preferences ? shell.preferences.schemes : []
                            C.MenuItem {
                                required property var modelData
                                text: modelData.label
                                checkable: true
                                checked: shell.preferences.scheme === modelData.name
                                onTriggered: shell.preferences.setScheme(modelData.name)
                            }
                        }
                        C.MenuSeparator {}
                        C.MenuItem {
                            text: t`Reduce motion`
                            checkable: true
                            checked: shell.preferences ? shell.preferences.calm : false
                            onTriggered: shell.preferences.setCalm(!shell.preferences.calm)
                        }
                        C.MenuSeparator {}
                        Repeater {
                            model: shell.preferences ? shell.preferences.shells : []
                            C.MenuItem {
                                required property var modelData
                                text: modelData.label
                                checkable: true
                                checked: shell.preferences.shell === modelData.name
                                onTriggered: shell.preferences.setShell(modelData.name)
                            }
                        }
                        C.MenuSeparator {}
                        C.MenuItem {
                            text: t`View this shell's source`
                            iconName: "code"
                            onTriggered: shell.site.showSource("desktop")
                        }
                    }
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    text: t`Go`
                    onClicked: goMenu.open()

                    C.Menu {
                        id: goMenu
                        y: parent.height

                        C.MenuItem {
                            text: t`Back`
                            iconName: "arrow-left"
                            onTriggered: shell.site.back()
                        }
                        C.MenuItem {
                            text: t`Forward`
                            iconName: "arrow-right"
                            onTriggered: shell.site.forward()
                        }
                        C.MenuSeparator {}
                        C.MenuItem {
                            text: t`Home`
                            iconName: "house"
                            onTriggered: shell.router.go("/")
                        }
                        C.MenuItem {
                            text: t`Docs`
                            iconName: "file-text"
                            onTriggered: shell.router.go("/start/")
                        }
                        C.MenuItem {
                            text: t`Demos`
                            iconName: "play"
                            onTriggered: shell.router.go("/demos/")
                        }
                        C.MenuItem {
                            text: t`Showcase`
                            iconName: "image"
                            onTriggered: shell.router.go("/showcase/")
                        }
                    }
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    text: t`Help`
                    onClicked: helpMenu.open()

                    C.Menu {
                        id: helpMenu
                        y: parent.height

                        C.MenuItem {
                            text: t`Your first app`
                            onTriggered: shell.router.go("/start/first-app/")
                        }
                        C.MenuItem {
                            text: t`Your own shell`
                            onTriggered: shell.router.go("/start/your-own-shell/")
                        }
                        C.MenuSeparator {}
                        C.MenuItem {
                            text: t`Ljós on GitHub`
                            iconName: "external-link"
                            onTriggered: shell.router.go(shell.router.github)
                        }
                    }
                }
            }
            Rectangle {
                y: parent.height - 1
                width: parent.width
                height: 1
                color: look.divider
            }
        }

        // The toolbar.
        Rectangle {
            id: toolBar
            z: 3
            y: menuBar.height
            width: parent.width
            height: 48
            color: look.canvas
            Accessible.role: Accessible.ToolBar
            Accessible.name: t`Toolbar`

            Row {
                x: 8
                anchors.verticalCenter: parent.verticalCenter
                spacing: 4

                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    iconName: "arrow-left"
                    display: C.Button.IconOnly
                    text: t`Back`
                    onClicked: shell.site.back()
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    iconName: "arrow-right"
                    display: C.Button.IconOnly
                    text: t`Forward`
                    onClicked: shell.site.forward()
                }
                C.Button {
                    anchors.verticalCenter: parent.verticalCenter
                    subtle: true
                    iconName: "house"
                    display: C.Button.IconOnly
                    text: t`Home`
                    onClicked: shell.router.go("/")
                }
                Item {
                    width: 12
                    height: 1
                }
                Item {
                    anchors.verticalCenter: parent.verticalCenter
                    width: Math.max(200, Math.min(480, toolBar.width - 520))
                    height: 36
                    Slot { name: "site.search" }
                }
            }
            Row {
                x: parent.width - width - 12
                anchors.verticalCenter: parent.verticalCenter
                spacing: 8

                Row {
                    anchors.verticalCenter: parent.verticalCenter
                    Slot { name: "site.github" }
                }
                Row {
                    anchors.verticalCenter: parent.verticalCenter
                    Slot { name: "site.switcher" }
                }
                Row {
                    anchors.verticalCenter: parent.verticalCenter
                    Slot { name: "site.preferences" }
                }
            }
            Rectangle {
                y: parent.height - 1
                width: parent.width
                height: 1
                color: look.divider
            }
        }
    }

    // The sidebar: every page.
    Rectangle {
        id: sidebar
        y: toolBar.y + toolBar.height
        width: 248
        height: statusBar.y - y
        color: look.surface
        Item {
            anchors.fill: parent
            Slot { name: "site.tree" }
        }
    }
    Rectangle {
        x: sidebar.width
        y: sidebar.y
        width: 1
        height: sidebar.height
        color: look.divider
    }

    // The pages open, as tabs, and the one shown under them.
    Item {
        id: documents
        x: sidebar.width + 1
        y: sidebar.y
        width: parent.width - x
        height: sidebar.height

        Rectangle {
            id: strip
            width: parent.width
            height: tabBar.height
            color: look.surface
            // Between the header and the page, so a landmark of its own.
            Accessible.role: Accessible.Section
            Accessible.name: t`Open pages`

            C.TabBar {
                id: tabBar
                width: parent.width
                Accessible.name: t`Open pages`

                Repeater {
                    model: shell.tabs
                    C.TabButton {
                        required property var modelData
                        required property int index
                        text: shell.router ? shell.router.nameOf(modelData) : modelData
                        iconName: modelData === "/" ? "house" : modelData.startsWith("/demos/") ? "play" : modelData === "/showcase/" ? "image" : "file-text"
                        onClicked: if (modelData !== shell.route) shell.router.go(modelData)
                    }
                }
            }
            Rectangle {
                y: parent.height - 1
                width: parent.width
                height: 1
                color: look.divider
            }
        }
        Item {
            id: page
            y: strip.height
            width: parent.width
            height: parent.height - y
            Slot { name: "site.page" }
        }
    }

    // The status bar.
    Rectangle {
        id: statusBar
        y: parent.height - height
        width: parent.width
        height: 28
        color: look.surface
        Accessible.role: Accessible.StatusBar
        Accessible.name: t`Status`

        Rectangle {
            width: parent.width
            height: 1
            color: look.divider
        }
        Row {
            x: 12
            anchors.verticalCenter: parent.verticalCenter
            spacing: 16

            Text {
                objectName: "statusRoute"
                text: shell.route
                color: look.textMuted
                font.family: shell.site ? shell.site.theme.mono : "monospace"
                font.pixelSize: 12
            }
            Text {
                objectName: "statusHydrated"
                visible: shell.hydratedMs >= 0
                text: t`Hydrated in ${hydratedMs} ms`
                color: look.textMuted
                font.family: look.sans
                font.pixelSize: 12
            }
            Text {
                objectName: "statusAlive"
                visible: shell.aliveCount > 0
                text: plural(aliveCount, { one: "# object alive", other: "# objects alive" })
                color: look.textMuted
                font.family: look.sans
                font.pixelSize: 12
            }
        }
    }
}

Landing.text:
// Ljós's Core before QtQuick: only its t`` is wanted here, and any name
// both have stays QtQuick's, the later import.
import Ljos.Core
import QtQuick
import Ljos.Blocks
import Site
import Demos
import "../Demos/later.js" as Later
import "../nav.js" as Nav

// The front page, read top to bottom: what Ljós is and a replay that
// shows it, what that means for agents with a live app to drive, a shell
// the reader changes here, TypeScript and the rest in a card each, a 3D
// demo, how the project works, and where to go next.
// Existing QML is named once, as the way in; the porting page tells
// that story. The words are the page's; how they stand (the hero beside
// its live app, the sections on the grid, rising in as they are first
// seen) is Site's, which each shell dresses.
Column {
    id: landing

    // The flickable the page scrolls in, for the demos to know when
    // they are on screen; and whether the window is a wide one.
    property var scroller: null
    property bool wide: true
    // Prose reads at a measure, whatever the page's width.
    readonly property int prose: Math.min(width, Theme.measure)
    readonly property int textWidth: width

    width: parent ? parent.width : 680
    // Sections stand well apart: each is one thing, said and shown.
    spacing: wide ? 2 * Theme.xxxl : Theme.xxxl + Theme.m
    // The grid's column and gap, for the sections that lay out on it.
    readonly property int gap: wide ? Theme.columnGap : Theme.compactColumnGap

    function follow(link) {
        Nav.go(link);
    }

    // What Ljós is, and beside it (under it, on a narrower page) the
    // replay that shows it: an app reshaped while it runs, the TypeScript
    // that does it and the controls to do it by hand, in the first screen.
    // The words take four of the grid's columns, and the replay stands
    // beside them where the rest is room for its code beside the app.
    Hero {
        width: parent.width
        wide: landing.wide
        wordsColumns: 4
        stageFrom: AgentReplay.sideBySide
        // Cyberpunk's console says it tersely (copy v2, shells.md).
        readonly property bool terse: Theme.shell === "cyberpunk"
        eyebrow: terse ? t`Live runtime on an open tree` : ""
        title: terse ? t`Reshape the running interface, human or agent.` : LandingCopy.headline
        subtitle: terse ? t`Inspect every node, patch state in flight, drop a new shell on the wire.` : LandingCopy.subhead
        caption: LandingCopy.heroCaption
        onFollowed: (link) => landing.follow(link)

        LinkButton {
            primary: true
            label: LandingCopy.start
            href: "/start/first-app/"
        }
        LinkButton {
            label: LandingCopy.tryDemo
            href: "/demos/"
        }

        // The replay, the page's first demo. Its poster is the session's
        // end, the board, drawn by the page: the hero is whole before
        // anything is fetched and for a reader who wants less motion. For
        // everyone else it starts itself, as the list, and is reshaped.
        stage: ReplayFrame {
            width: parent.width
            scroller: landing.scroller
            aspect: 0.1
            // As high as it says (AgentView): the board at its fullest, and,
            // stacked, its code after that.
            note: LandingCopy.heroNote
            what: LandingCopy.heroWhat
            poster: Component {
                AgentPoster {}
            }
            source: Later.agent
        }
    }

    // Built for agents: what the replay shows, said, beside an app to
    // drive by hand, its source, the Observer and an agent's steps.
    Rise {
        Capability {
            id: agentic
            wide: landing.wide
            // Cyberpunk shows the live app as a console, under the words,
            // where the section is wide enough for one (DeviceFrame).
            stacked: Theme.consoleAt(width)
            eyebrow: LandingCopy.agenticEyebrow
            title: LandingCopy.agenticHeadline
            body: LandingCopy.agenticBody
            onFollowed: (link) => landing.follow(link)

            HeroStage {
                width: agentic.exampleWidth
            }
        }
    }

    // Make it your own: the point, said, shown in code, and run, the
    // words on the right this time.
    Rise {
        Capability {
            id: ownShell
            wide: landing.wide
            flip: true
            eyebrow: t`Malleable`
            title: t`Make it your own`
            body: t`An app’s layout doesn’t have to be fixed. Let people, or their agents, replace it live, without losing their work. If an edit won’t compile, the last working layout stays.`
            onFollowed: (link) => landing.follow(link)

            CodeBlock {
                width: ownShell.exampleWidth
                scroller: landing.scroller
                lang: "qml"
                code: LandingCode.ownShell.code
                rich: LandingCode.ownShell.rich
            }
            // What to do with the playground under the section.
            Text {
                width: ownShell.exampleWidth
                textFormat: Text.RichText
                color: Theme.text
                linkColor: Theme.link
                font.family: Theme.sans
                font.pixelSize: Theme.bodySize
                lineHeightMode: Text.FixedHeight
                lineHeight: Theme.bodyLine
                wrapMode: Text.Wrap
                topPadding: Theme.m
                text: t`<b>Try it on this shop.</b> Add something to the basket, then move <code>StatusSlot</code> in the code below. The layout changes and the basket keeps its items. Make a typo and the shop keeps working while you fix it.`
            }
        }
        Item {
            width: parent.width
            height: landing.wide ? Theme.xxl : Theme.xl
        }
        // The flagship malleable demo mounts into this slot, the page's
        // whole width: a small app whose shell the visitor rewrites on
        // the page, its state kept, a broken edit falling back with the
        // error shown. It is the page's point, so it is made with the
        // page, a playground and not an illustration.
        Slot {
            name: "showcase-shell"
            delegate: Component {
                PantryDemo {
                    width: landing.width
                    observerWhenIdle: false
                }
            }
        }
    }

    // The rest of what Ljós is, a card each, four of the grid's twelve
    // columns apiece.
    Rise {
        Grid {
            id: points

            readonly property int cardWidth: landing.wide ? Math.floor((landing.width - 2 * landing.gap) / 3) : landing.width
            readonly property real tallest: Math.max(typed.contentHeight, observed.contentHeight, stable.contentHeight)

            width: parent.width
            columns: landing.wide ? 3 : 1
            columnSpacing: landing.gap
            rowSpacing: landing.gap

            FeatureCard {
                id: typed
                width: points.cardWidth
                height: landing.wide ? points.tallest : contentHeight
                mark: "01"
                title: t`TypeScript first`
                body: t`Write app logic in TypeScript and catch mistakes with <code>ljos check</code>. Use Rust where you need it. Already have QML? <a href="/language/porting-from-qt/">Bring it along</a>.`
                onFollowed: (link) => landing.follow(link)
            }
            FeatureCard {
                id: observed
                width: points.cardWidth
                height: landing.wide ? points.tallest : contentHeight
                mark: "02"
                title: t`See inside a running app`
                body: t`Open the Observer to see every part of your app, where its values come from, and what’s using time and memory. Your agent gets the same view.`
                onFollowed: (link) => landing.follow(link)
            }
            FeatureCard {
                id: stable
                width: points.cardWidth
                height: landing.wide ? points.tallest : contentHeight
                mark: "03"
                title: t`Fast, and quiet when idle`
                body: t`Our benchmark mail app shows its first frame in under 90 ms, uses under 24 MiB of private memory, and takes 0 % CPU when idle.<br><br>These are <a href="https://github.com/hal-c2/ljos-ui/blob/main/docs/BENCHMARKS.md">native numbers</a> from Linux on 10\u00a0Nov\u00a02026. They don’t measure this web page.`
                onFollowed: (link) => landing.follow(link)
            }
        }
    }

    // A demo of what the engine draws, the words on the left again.
    Rise {
        Capability {
            id: seeItRun
            wide: landing.wide
            eyebrow: t`Live in the page`
            title: t`See it run`
            body: t`Once this 3D scene runs, drag to look around, and scroll or pinch to zoom. The <a href="/demos/">live demos</a> have more, including a car cockpit and a smartwatch you can edit. Each keeps a picture and its description where the browser lacks the WebAssembly or WebGL 2 it needs.`
            onFollowed: (link) => landing.follow(link)

            // The showcase mounts here: a 3D scene to orbit, made once the
            // reader presses its Run, its picture standing until then — and
            // for good where the browser cannot run it.
            Slot {
                name: "showcase"
                delegate: Component {
                    DemoFrame {
                        width: seeItRun.exampleWidth
                        scroller: landing.scroller
                        needs: "webgl2"
                        picture: "/pictures/demo-orbit.webp"
                        pictureDark: "/pictures/demo-orbit-dark.webp"
                        what: t`the 3D demo`
                        description: t`A lit 3D scene of shapes on a floor. Drag to turn it.`
                        source: Later.orbit
                    }
                }
            }
        }
    }

    // How the project means to work together: the headline on the
    // grid's first five columns, the words on the other seven.
    // It stands in a panel of its own, on the hero's wash, so the words
    // read as the project's own statement and not as one more section.
    Rise {
        Rectangle {
            id: togetherPanel

            readonly property int pad: landing.wide ? Theme.xxl : Theme.l

            width: parent.width
            height: together.height + 2 * pad
            radius: Theme.radiusLarge
            color: Theme.surface
            border.color: Theme.divider
            border.width: 1
            clip: true
            gradient: Gradient {
                orientation: Gradient.Horizontal
                GradientStop { position: 0; color: Theme.washStart }
                GradientStop { position: 0.55; color: Theme.surface }
            }

            Item {
                id: together

                readonly property real column: (width - (Theme.columns - 1) * Theme.columnGap) / Theme.columns
                readonly property int wordsX: landing.wide ? Math.round(5 * column + 5 * Theme.columnGap) : 0

                x: togetherPanel.pad
                y: togetherPanel.pad
                width: parent.width - 2 * togetherPanel.pad
                height: landing.wide ? Math.max(togetherHeading.height, togetherWords.implicitHeight) : togetherHeading.height + Theme.m + togetherWords.implicitHeight

                Heading {
                    id: togetherHeading
                    width: landing.wide ? together.wordsX - Theme.columnGap : parent.width
                    level: "display"
                    wide: landing.wide
                    text: t`Built together`
                }
                Text {
                    id: togetherWords
                    x: together.wordsX
                    y: landing.wide ? Theme.xs : togetherHeading.height + Theme.m
                    width: Math.min(parent.width - x, Theme.measure)
                    textFormat: Text.RichText
                    color: Theme.textMuted
                    linkColor: Theme.link
                    font.family: Theme.sans
                    font.pixelSize: Theme.bodySize
                    lineHeightMode: Text.FixedHeight
                    lineHeight: Theme.bodyLine
                    wrapMode: Text.Wrap
                    text: t`Ljós strives to follow the <a href="https://community-software.org/">Community Software</a> principles: we build it together, as peers, in the open.<br><br>Everyone is welcome.<br>We are peers.<br>Every contribution counts.<br>Influence grows from participation.<br>Be kind to people, rigorous with ideas.<br>“No” and “not yet” are valid answers.<br>Look after yourself and each other.<br><br>Code is one way to help. Testing, docs, design, translation and accessibility reviews count as much, and questions from newcomers are welcome.`
                    onLinkActivated: (link) => landing.follow(link)
                }
            }
        }
    }

    // Where to read next: four cards abreast where there is room.
    Rise {
        Column {
            width: parent.width
            spacing: Theme.l

            Heading {
                width: parent.width
                level: "display"
                wide: landing.wide
                text: t`Start reading`
            }
            Grid {
                id: reading

                columns: landing.width >= 1100 ? 4 : landing.wide ? 2 : 1
                readonly property int cardWidth: Math.floor((landing.width - (columns - 1) * landing.gap) / columns)
                readonly property real tallestTop: columns === 4 ? Math.max(map.contentHeight, first.contentHeight, demosCard.contentHeight, goals.contentHeight) : Math.max(map.contentHeight, first.contentHeight)
                readonly property real tallestBottom: columns === 4 ? tallestTop : Math.max(demosCard.contentHeight, goals.contentHeight)

                width: parent.width
                columnSpacing: landing.gap
                rowSpacing: landing.gap

                FeatureCard {
                    id: map
                    width: reading.cardWidth
                    height: reading.columns > 1 ? reading.tallestTop : contentHeight
                    title: t`What is Ljós?`
                    href: "/start/"
                    body: t`The big picture, in plain words.`
                    onFollowed: (link) => landing.follow(link)
                }
                FeatureCard {
                    id: first
                    width: reading.cardWidth
                    height: reading.columns > 1 ? reading.tallestTop : contentHeight
                    title: t`Your first app`
                    href: "/start/first-app/"
                    body: t`Open a window, then change it while it runs.`
                    onFollowed: (link) => landing.follow(link)
                }
                FeatureCard {
                    id: demosCard
                    width: reading.cardWidth
                    height: reading.columns > 1 ? reading.tallestBottom : contentHeight
                    title: t`Live demos`
                    href: "/demos/"
                    body: t`Try Ljós in your browser, with nothing to install.`
                    onFollowed: (link) => landing.follow(link)
                }
                FeatureCard {
                    id: goals
                    width: reading.cardWidth
                    height: reading.columns > 1 ? reading.tallestBottom : contentHeight
                    title: t`Goals and principles`
                    href: "/quality/principles/"
                    body: t`What we care about, and what we leave out on purpose.`
                    onFollowed: (link) => landing.follow(link)
                }
            }
        }
    }
}

DemosPage.text:
// Ljós's Core before QtQuick: only its t`` is wanted here, and any name
// both have stays QtQuick's, the later import.
import Ljos.Core
import QtQuick
import Ljos.Blocks
import Site
import Demos
import "../Demos/later.js" as Later
import "../nav.js" as Nav

// The demos page: complete Ljós apps running in the page, flagship
// first. Each demo stands in its named Slot as the slot's own
// delegate. The flagship is made with the page, so the prerendered
// page holds it as first made and hydration takes it over in place.
// The others stand in a frame their own size from the first paint,
// a picture of each in it, and are made once the reader presses its
// Run; a browser without what one needs keeps the picture, and its
// words say what it shows. Each of those waits for its Run (Runner):
// what runs on a page is the reader's to start, and at most three run
// at once. The flagship has no Run: it holds still until pressed, as a
// plain example does, and its shell is the one compiled with the page. Nothing on this page is needed to read it. The sections
// are written out, not repeated over a model: a Slot's delegate is
// made by the Slot, in the Slot's place, and a Repeater's model is
// not its to give.
Column {
    id: demos

    property var scroller: null
    property bool wide: true
    readonly property int textWidth: width

    width: parent ? parent.width : 680
    spacing: demos.wide ? Theme.xxxl : Theme.xxl
    topPadding: demos.wide ? Theme.xl : Theme.m

    Column {
        width: parent.width
        spacing: Theme.l

        Heading {
            width: parent.width
            level: "display"
            wide: demos.wide
            headingLevel: 1
            text: t`Live demos`
        }
        Text {
            width: Math.min(parent.width, Theme.measure)
            text: t`Each demo is a complete Ljós app that passes ljos check, compiled ahead of time and mounted in this page. Once a framed demo runs, switch between light and dark themes in the header to watch it follow, and edit the live source in the Pantry and on the cockpit and smartwatch pages. A demo keeps its picture and description where the browser lacks the WebAssembly or WebGL 2 it needs.`
            color: Theme.textMuted
            font.family: Theme.sans
            font.pixelSize: Theme.subtitleSize - 1
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.subtitleLine - 2
            wrapMode: Text.Wrap
        }
    }

    DemoSection {
        width: demos.textWidth
        wide: demos.wide
        title: t`A shell you rewrite`
        body: t`Add items to the basket, then edit Shell.qml right in the page. Move a Slot to rearrange the interface while the basket keeps its items, or introduce a syntax error: the last shell that compiled keeps running, with the compiler message shown beside the editor. Switch light and dark themes to watch both shells follow.`

        Slot {
            name: "demo-shell"
            delegate: Component {
                PantryDemo {
                    width: demos.textWidth
                }
            }
        }
    }

    // Each pro demo's card (Demos/pro.json): its picture, and the way to
    // its own page.
    Repeater {
        model: Content.pro
        delegate: DemoSection {
            id: card
            required property var modelData
            width: demos.textWidth
            wide: demos.wide
            title: modelData.card
            body: modelData.cardBody

            Column {
                width: demos.textWidth
                spacing: Theme.s

                // The picture on the same rounded panel as the demos that
                // run in the page, so every demo reads as one kind of thing.
                Rectangle {
                    width: parent.width
                    height: Math.round(width * card.modelData.height / card.modelData.width)
                    radius: Theme.radiusLarge
                    color: Theme.stage
                    clip: true

                    Text {
                        width: parent.width
                        height: parent.height
                        textFormat: Text.RichText
                        text: Nav.picture("/demos/", Nav.proPicture(card.modelData, Theme.picked, Theme.dark), width, height, card.modelData.cardAlt)
                    }
                }
                LinkButton {
                    label: card.modelData.open
                    href: card.modelData.route
                }
            }
        }
    }

    DemoSection {
        width: demos.textWidth
        wide: demos.wide
        title: t`3D you can orbit`
        body: t`A lit 3D scene rendered by the same engine that runs natively on desktop and mobile. Once it runs, drag to orbit, scroll or pinch to zoom, and switch light and dark themes to watch the scene adapt.`

        Slot {
            name: "demo-orbit"
            delegate: Component {
                DemoFrame {
                    width: demos.textWidth
                    scroller: demos.scroller
                    needs: "webgl2"
                    route: "/demos/"
                    picture: "/pictures/demo-orbit.webp"
                    pictureDark: "/pictures/demo-orbit-dark.webp"
                    what: t`the 3D demo`
                    description: t`A lit 3D scene of shapes on a floor. Drag to turn it.`
                    source: Later.orbit
                }
            }
        }
    }

    DemoSection {
        width: demos.textWidth
        wide: demos.wide
        title: t`A shader effect`
        body: t`Once it runs, move the pointer across the card to stir the light and tap to cycle colours. The shader runs over live app content rather than a pre-rendered texture, and follows the page's light and dark themes.`

        Slot {
            name: "demo-shader"
            delegate: Component {
                DemoFrame {
                    width: demos.textWidth
                    scroller: demos.scroller
                    needs: "webgl2"
                    route: "/demos/"
                    picture: "/pictures/demo-shader.webp"
                    pictureDark: "/pictures/demo-shader-dark.webp"
                    what: t`the shader demo`
                    description: t`Light pooling over a card of text, following the pointer.`
                    source: Later.shader
                }
            }
        }
    }

    DemoSection {
        width: demos.textWidth
        wide: demos.wide
        title: t`A whole app`
        body: t`A bird field guide. Once it runs, filter the list by typing in Search, pick a species to read its notes, mark birds as seen to update the counter, and switch light and dark themes while keeping your selection.`

        Slot {
            name: "demo-app"
            delegate: Component {
                DemoFrame {
                    width: demos.textWidth
                    scroller: demos.scroller
                    needs: "wasm"
                    compiles: false
                    route: "/demos/"
                    // Narrow, the guide stacks its list over its detail.
                    least: 520
                    picture: "/pictures/demo-app.webp"
                    pictureDark: "/pictures/demo-app-dark.webp"
                    what: t`the field guide`
                    description: t`A field guide to birds: a list of species beside the one picked, with notes and a count of those seen.`
                    source: Later.fieldGuide
                }
            }
        }
    }

    DemoSection {
        width: demos.textWidth
        wide: demos.wide
        title: t`Motion`
        body: t`Once it runs, click Shuffle the tiles to watch them reorder on a single eased value, and press and drag in the spring tray so the puck springs after your pointer. When the motion settles, nothing ticks and an app at rest uses 0 % CPU.`

        Slot {
            name: "demo-motion"
            delegate: Component {
                DemoFrame {
                    width: demos.textWidth
                    scroller: demos.scroller
                    needs: "wasm"
                    compiles: false
                    route: "/demos/"
                    // Narrow, Motion's controls wrap onto two lines.
                    least: 440
                    picture: "/pictures/demo-motion.webp"
                    pictureDark: "/pictures/demo-motion-dark.webp"
                    what: t`the motion demo`
                    description: t`Tiles that shuffle and settle, driven by one eased value.`
                    source: Later.motion
                }
            }
        }
    }
}

ShowcasePage.text:
// Ljós's Core before QtQuick: only its t`` is wanted here, and any name
// both have stays QtQuick's, the later import.
import Ljos.Core
import QtQuick
import Site

// The showcase: apps built with Ljós, each recorded as it runs. The
// apps are data (Showcase/products.json, carried in ShowcaseApps.apps),
// so another is another entry and its files, and no app is named here.
Column {
    id: showcase

    // Wide or not as it is made, from what loads it (PageView's Loader
    // says), so a phone never lays out the wide page first and then again.
    property bool wide: parent && parent.wide !== undefined ? parent.wide : true

    width: parent ? parent.width : 680
    spacing: showcase.wide ? Theme.xxxl + Theme.l : Theme.xxl
    topPadding: showcase.wide ? Theme.xl : Theme.m

    Column {
        width: parent.width
        spacing: Theme.s

        Text {
            width: parent.width
            text: t`Built with Ljós`
            color: Theme.text
            font.family: Theme.sans
            font.pixelSize: showcase.wide ? Theme.displaySize : Theme.compactDisplaySize
            font.weight: Font.Bold
            lineHeightMode: Text.FixedHeight
            lineHeight: showcase.wide ? Theme.displayLine : Theme.compactDisplayLine
            wrapMode: Text.Wrap
            readonly property int headingLevel: 1
            Accessible.role: Accessible.Heading
        }
        Text {
            width: Math.min(parent.width, Theme.measure)
            text: t`Apps that run on Ljós today, recorded as they run. Each capture says what it shows about Ljós, and each app links to its source.`
            color: Theme.textMuted
            font.family: Theme.sans
            font.pixelSize: Theme.subtitleSize - 1
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.subtitleLine - 2
            wrapMode: Text.Wrap
        }
    }

    Repeater {
        model: ShowcaseApps.apps
        ShowcaseApp {
            required property var modelData
            product: modelData
            width: showcase.width
            wide: showcase.wide
        }
    }
}

DocPage.text:
// Ljós's Core before QtQuick: only its t`` is wanted here, and any name
// both have stays QtQuick's, the later import.
import Ljos.Core
import QtQuick
import Site
import "../nav.js" as Nav

// One docs page: its title, what it is about, then its blocks in
// order — headings a contents list can land on, prose, lists,
// tables, pictures and code. The blocks are the Markdown source's
// (`ljos-web/markdown`), read at build time; this page only shows
// them. Every block is made whether or not it is on screen, so a
// prerendered page holds the whole text for a reader with no script.
//
// Each block makes only its own kind's face: a Repeater of one for
// that kind, none for the others. A Repeater makes its delegates as
// it is made, so the block is there as the page is made, in a
// prerender as in a browser; a `Loader` whose component is a binding
// would load a frame later, after a prerender has written the page.
Column {
    id: doc

    property string route: "/"
    // The page this route names, as the shell was made with it: known
    // as the page is made, in a prerender as in a browser.
    property var page: null
    // The pages before and after this one, in the sidebar's order.
    readonly property var previous: page ? page.previous : null
    readonly property var next: page ? page.next : null
    readonly property bool narrow: width < 600

    // The flickable that holds this column, named by the shell so a
    // contents press can land on its heading.
    property var scroller: null

    // A link in the page's text, for the shell to follow.
    signal followed(string href)

    function scrollToAnchor(anchor) {
        if (!doc.scroller)
            return;
        for (var i = 0; i < blocks.count; i++) {
            var item = blocks.itemAt(i);
            if (item && item.anchor === anchor) {
                var at = item.mapToItem(doc.scroller.contentItem, 0, 0);
                doc.scroller.contentY = Math.max(0, Math.min(at.y - Theme.l, doc.scroller.contentHeight - doc.scroller.height));
                return;
            }
        }
    }

    spacing: Theme.m

    Text {
        id: missingDoc
        readonly property string startLink: Nav.anchor(Nav.at(Content.base, "/start/"), t`What is Ljós?`, true)
        width: parent.width
        visible: !doc.page && doc.route !== ""
        textFormat: Text.RichText
        text: t`There is no page at this address. The address may have moved — search, or begin at ${missingDoc.startLink}.`
        color: Theme.text
        linkColor: Theme.link
        font.family: Theme.sans
        font.pixelSize: Theme.bodySize
        lineHeightMode: Text.FixedHeight
        lineHeight: Theme.bodyLine
        wrapMode: Text.Wrap
        onLinkActivated: (link) => doc.followed(link)
    }
    Column {
        width: parent.width
        visible: doc.page !== null
        spacing: Theme.s
        bottomPadding: Theme.s

        // The page's title is its outline's one first-level heading,
        // in the look's display face.
        Heading {
            width: parent.width
            level: "display"
            wide: !doc.narrow
            headingLevel: 1
            text: doc.page ? doc.page.title : ""
        }
        Text {
            width: parent.width
            visible: text !== ""
            text: doc.page ? (doc.page.description || "") : ""
            color: Theme.textMuted
            font.family: Theme.sans
            font.pixelSize: Theme.subtitleSize
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.subtitleLine
            wrapMode: Text.Wrap
        }
    }

    Repeater {
        id: blocks
        model: doc.page ? doc.page.blocks : []

        Column {
            id: blockItem

            required property var modelData
            required property int index

            readonly property string kind: String(modelData.kind)
            readonly property string anchor: kind === "heading" ? String(modelData.anchor) : ""

            width: doc.width
            spacing: 0

            // A heading: space above it, more for a bigger one. It is
            // named by its anchor, so its address lands on it in a page
            // with no script too.
            Repeater {
                model: blockItem.kind === "heading" ? 1 : 0
                Text {
                    readonly property int level: blockItem.modelData.level || 2
                    width: doc.width
                    topPadding: level <= 2 ? Theme.xl : Theme.m
                    text: "<a name=\"" + blockItem.anchor + "\"></a>" + blockItem.modelData.rich
                    textFormat: Text.RichText
                    color: Theme.onCanvasStrong
                    linkColor: Theme.link
                    font.family: Theme.sans
                    font.letterSpacing: level <= 2 ? -0.3 : 0
                    font.pixelSize: level <= 2 ? Theme.headlineSize - (doc.narrow ? 4 : 0) : level === 3 ? Theme.subtitleSize : Theme.bodySize
                    font.weight: level <= 3 ? Font.DemiBold : Font.Bold
                    lineHeightMode: Text.FixedHeight
                    lineHeight: level <= 2 ? Theme.headlineLine - (doc.narrow ? 4 : 0) : level === 3 ? Theme.subtitleLine : Theme.bodyLine
                    wrapMode: Text.Wrap
                    // Said at the level the docs wrote it: their sections
                    // are second level, under the page's title.
                    readonly property int headingLevel: Math.max(2, level)
                    Accessible.role: Accessible.Heading
                    onLinkActivated: (link) => doc.followed(link)
                }
            }
            // Prose.
            Repeater {
                model: blockItem.kind === "para" ? 1 : 0
                Text {
                    width: doc.width
                    text: blockItem.modelData.rich
                    textFormat: Text.RichText
                    color: Theme.text
                    linkColor: Theme.link
                    font.family: Theme.sans
                    font.pixelSize: Theme.bodySize
                    lineHeightMode: Text.FixedHeight
                    lineHeight: Theme.bodyLine + Theme.xxs
                    wrapMode: Text.Wrap
                    onLinkActivated: (link) => doc.followed(link)
                }
            }
            // A list.
            Repeater {
                model: blockItem.kind === "list" ? 1 : 0
                Column {
                    width: doc.width
                    spacing: Theme.xs

                    Repeater {
                        model: blockItem.modelData.items
                        Row {
                            required property var modelData
                            required property int index
                            width: doc.width
                            spacing: Theme.xs

                            Text {
                                width: blockItem.modelData.ordered ? 24 : 16
                                horizontalAlignment: Text.AlignRight
                                text: blockItem.modelData.ordered ? (index + 1) + "." : "•"
                                color: Theme.textMuted
                                font.family: Theme.sans
                                font.pixelSize: Theme.bodySize
                                lineHeightMode: Text.FixedHeight
                                lineHeight: Theme.bodyLine + Theme.xxs
                                // A step's number is its order, which the
                                // reader hears; a bullet is only a mark.
                                Accessible.ignored: !blockItem.modelData.ordered
                            }
                            Text {
                                width: doc.width - (blockItem.modelData.ordered ? 24 : 16) - Theme.xs
                                text: modelData
                                textFormat: Text.RichText
                                color: Theme.text
                                linkColor: Theme.link
                                font.family: Theme.sans
                                font.pixelSize: Theme.bodySize
                                lineHeightMode: Text.FixedHeight
                                lineHeight: Theme.bodyLine + Theme.xxs
                                wrapMode: Text.Wrap
                                onLinkActivated: (link) => doc.followed(link)
                            }
                        }
                    }
                }
            }
            // A table: its head row, then its rows, the columns sharing
            // the page's width; a narrow page scrolls it sideways.
            Repeater {
                model: blockItem.kind === "table" ? 1 : 0
                Rectangle {
                    id: tableFrame
                    readonly property var head: blockItem.modelData.head
                    readonly property var rows: blockItem.modelData.rows
                    readonly property int cols: Math.max(1, head.length)
                    readonly property int cellWidth: Math.max(140, Math.floor((doc.width - 2) / cols))

                    width: doc.width
                    height: table.height + 2
                    radius: Theme.radius
                    color: Theme.canvas
                    border.color: Theme.divider
                    border.width: 1
                    clip: true

                    Flickable {
                        x: 1
                        y: 1
                        width: parent.width - 2
                        height: table.height
                        contentWidth: table.width
                        contentHeight: table.height
                        flickableDirection: Flickable.HorizontalFlick
                        clip: true

                        Column {
                            id: table

                            Row {
                                Repeater {
                                    model: tableFrame.head
                                    Rectangle {
                                        required property var modelData
                                        width: tableFrame.cellWidth
                                        height: headRow.height
                                        color: Theme.surface
                                        Text {
                                            id: headCell
                                            x: Theme.s
                                            y: Theme.xs
                                            width: parent.width - 2 * Theme.s
                                            text: modelData
                                            textFormat: Text.RichText
                                            color: Theme.text
                                            linkColor: Theme.link
                                            font.family: Theme.sans
                                            font.pixelSize: Theme.captionSize + 1
                                            font.weight: Font.DemiBold
                                            lineHeightMode: Text.FixedHeight
                                            lineHeight: Theme.captionLine
                                            wrapMode: Text.Wrap
                                            onLinkActivated: (link) => doc.followed(link)
                                        }
                                    }
                                }
                                id: headRow
                                height: {
                                    var tallest = 0;
                                    for (var i = 0; i < children.length; i++) {
                                        var cell = children[i].children[0];
                                        if (cell)
                                            tallest = Math.max(tallest, cell.implicitHeight);
                                    }
                                    return tallest + 2 * Theme.xs;
                                }
                            }
                            Repeater {
                                model: tableFrame.rows
                                Row {
                                    id: bodyRow
                                    required property var modelData
                                    height: {
                                        var tallest = 0;
                                        for (var i = 0; i < children.length; i++) {
                                            var cell = children[i].children[1];
                                            if (cell)
                                                tallest = Math.max(tallest, cell.implicitHeight);
                                        }
                                        return tallest + 2 * Theme.xs + 1;
                                    }
                                    Repeater {
                                        model: bodyRow.modelData
                                        Item {
                                            required property var modelData
                                            width: tableFrame.cellWidth
                                            height: bodyRow.height
                                            Rectangle {
                                                width: parent.width
                                                height: 1
                                                color: Theme.divider
                                            }
                                            Text {
                                                x: Theme.s
                                                y: Theme.xs + 1
                                                width: parent.width - 2 * Theme.s
                                                text: modelData
                                                textFormat: Text.RichText
                                                color: Theme.text
                                                linkColor: Theme.link
                                                font.family: Theme.sans
                                                font.pixelSize: Theme.captionSize + 1
                                                lineHeightMode: Text.FixedHeight
                                                lineHeight: Theme.captionLine
                                                wrapMode: Text.Wrap
                                                onLinkActivated: (link) => doc.followed(link)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            // Code, through the site's one code-block face: plain,
            // or live where the build ran it.
            Repeater {
                model: blockItem.kind === "code" || blockItem.kind === "live" ? 1 : 0
                CodeBlock {
                    readonly property bool isCode: blockItem.kind === "code"
                    width: doc.width
                    scroller: doc.scroller
                    lang: blockItem.modelData.lang || ""
                    code: isCode ? (blockItem.modelData.code || "") : ""
                    rich: blockItem.modelData.rich || ""
                    harness: isCode ? (blockItem.modelData.harness || "") : ""
                    file: isCode ? (blockItem.modelData.file || "") : ""
                    group: isCode ? (blockItem.modelData.group || "") : ""
                    before: isCode ? (blockItem.modelData.before || false) : false
                    live: isCode ? null : blockItem.modelData.live
                }
            }
            // A quote, or an admonition the Markdown named: a bar of
            // the accent beside it, and its kind said first.
            Repeater {
                model: blockItem.kind === "quote" ? 1 : 0
                Rectangle {
                    width: doc.width
                    height: quoteWords.implicitHeight + 2 * Theme.m
                    radius: Theme.radiusSmall
                    color: Theme.surface
                    border.color: Theme.divider
                    border.width: 1

                    Rectangle {
                        width: 4
                        height: parent.height
                        radius: 2
                        color: Theme.accent
                    }
                    Column {
                        id: quoteWords
                        x: Theme.l
                        y: Theme.m
                        width: parent.width - Theme.l - Theme.m
                        spacing: Theme.xxs

                        Text {
                            visible: !!blockItem.modelData.note
                            text: blockItem.modelData.note ? String(blockItem.modelData.note).charAt(0).toUpperCase() + String(blockItem.modelData.note).slice(1) : ""
                            color: Theme.link
                            font.family: Theme.sans
                            font.pixelSize: Theme.captionSize
                            font.weight: Font.Bold
                            lineHeightMode: Text.FixedHeight
                            lineHeight: Theme.captionLine
                        }
                        Text {
                            width: parent.width
                            text: blockItem.modelData.rich
                            textFormat: Text.RichText
                            color: Theme.text
                            linkColor: Theme.link
                            font.family: Theme.sans
                            font.pixelSize: Theme.bodySize
                            lineHeightMode: Text.FixedHeight
                            lineHeight: Theme.bodyLine
                            wrapMode: Text.Wrap
                            onLinkActivated: (link) => doc.followed(link)
                        }
                    }
                }
            }
            // A picture, with the words that say what it is.
            Repeater {
                model: blockItem.kind === "image" ? 1 : 0
                Column {
                    width: doc.width
                    spacing: Theme.xs

                    // A picture with no words is decoration, left out
                    // of what is read rather than read as nameless.
                    Image {
                        Accessible.role: blockItem.modelData.alt ? Accessible.Graphic : Accessible.NoRole
                        Accessible.name: blockItem.modelData.alt || ""
                        Accessible.ignored: !blockItem.modelData.alt
                        source: blockItem.modelData.src || ""
                        width: Math.min(implicitWidth > 0 ? implicitWidth : doc.width, doc.width)
                        height: implicitWidth > 0 ? width * implicitHeight / implicitWidth : Math.round(doc.width * 9 / 16)
                        fillMode: Image.PreserveAspectFit
                    }
                    Text {
                        width: doc.width
                        visible: text !== ""
                        text: blockItem.modelData.alt || ""
                        color: Theme.textMuted
                        font.family: Theme.sans
                        font.pixelSize: Theme.captionSize
                        lineHeightMode: Text.FixedHeight
                        lineHeight: Theme.captionLine
                        wrapMode: Text.Wrap
                    }
                }
            }
            // A rule.
            Repeater {
                model: blockItem.kind === "rule" ? 1 : 0
                Item {
                    width: doc.width
                    height: Theme.l
                    Rectangle {
                        anchors.verticalCenter: parent.verticalCenter
                        width: parent.width
                        height: 1
                        color: Theme.divider
                    }
                }
            }
        }
    }

    // Where reading goes on: the page before this one and the page
    // after, each a link of the page's own, one to a line so a long
    // title has the width.
    Column {
        visible: doc.page !== null
        width: parent.width
        spacing: 10

        Rectangle {
            width: parent.width
            height: 1
            color: Theme.border
        }
        NavLink {
            id: prevLink
            visible: doc.previous !== null
            readonly property string title: doc.previous ? doc.previous.title : ""
            label: doc.previous ? t`← ${prevLink.title}` : ""
            to: doc.previous ? doc.previous.route : "/"
            Accessible.name: doc.previous ? t`Previous: ${prevLink.title}` : ""
        }
        NavLink {
            id: nextLink
            visible: doc.next !== null
            x: parent.width - width
            readonly property string title: doc.next ? doc.next.title : ""
            label: doc.next ? t`${nextLink.title} →` : ""
            to: doc.next ? doc.next.route : "/"
            Accessible.name: doc.next ? t`Next: ${nextLink.title}` : ""
        }
    }
}

ProDemoPage.text:
import QtQuick
import Site
import "../Demos/pro-live.js" as Live
import "../nav.js" as Nav

// A pro demo's page (Demos/pro.json, `demo` its entry): a whole app
// running in the page, with its files below it to read, change and
// download. An edit is compiled in the page against the other files as
// they stand and, once it compiles, the app is made again from it; one
// that does not is refused with what broke, and the last app that
// compiled stays. The files come with the page's script
// (Demos/<name>-project.json), not in its HTML: a reader without script
// has the app's picture and a link to each file to download.
Column {
    id: page

    required property var demo
    property var scroller: null
    property bool wide: true

    // The files, once they came: [{ path, lang, code, rich }].
    property var files: []
    property string path: page.demo.entry
    // What the reader changed, by file; a file they set back is not here.
    property var edits: ({})
    property var live: null
    property string said: ""
    // What the reader's current edits made the compiler say, by file:
    // the editor's squiggles. Only the compile of the edits as they
    // still stand writes it, so one that lands late says nothing.
    property var marks: ({})
    property bool runs: true
    // The text last given to the editor by the page, so the editor saying
    // it back is not taken for an edit.
    property string own: ""
    readonly property var file: files.find((entry) => entry.path === path) ?? null
    readonly property string sourceBase: Content.base + "demos/" + page.demo.name + "/source/"

    width: parent ? parent.width : 1040
    spacing: Theme.l
    topPadding: page.wide ? Theme.xl : Theme.m

    Component.onCompleted: page.open()
    // The shell keeps this page from one pro demo's route to the next, so
    // a new demo starts it afresh, and what was asked for the last one is
    // dropped when it comes.
    onDemoChanged: page.open()

    function open() {
        const name = page.demo.name;
        debounce.stop();
        files = [];
        edits = {};
        live = null;
        said = "";
        marks = {};
        runs = true;
        own = "";
        path = page.demo.entry;
        Live.load(name).then((project) => {
            if (page.demo.name !== name)
                return;
            page.files = project.files;
            page.show(page.path);
        });
        Live.needsWasm().then((why) => {
            if (why && page.demo.name === name) {
                page.runs = false;
                page.said = why;
            }
        });
    }

    function show(next) {
        path = next;
        const text = Object.hasOwn(edits, next) ? edits[next] : (file ? file.code : "");
        own = text;
        editor.text = text;
        editor.diagnostics = marks[next] || [];
    }
    function edited(text) {
        if (text === own || !file)
            return;
        own = text;
        const next = Object.assign({}, edits);
        if (text === file.code)
            delete next[path];
        else
            next[path] = text;
        edits = next;
        debounce.restart();
    }
    function apply() {
        if (!runs)
            return;
        const asked = edits;
        const name = page.demo.name;
        Live.compile(name, page.demo.entry, asked, sourceBase).then((made) => {
            if (asked !== page.edits || page.demo.name !== name)
                return;
            page.said = "";
            page.marks = {};
            page.live = Object.keys(asked).length > 0 ? made : null;
            editor.diagnostics = [];
        }, (error) => {
            if (asked !== page.edits || page.demo.name !== name)
                return;
            page.said = error.message;
            page.marks = error.diagnostics || {};
            editor.diagnostics = page.marks[page.path] || [];
        });
    }
    function reset() {
        // An edit waiting to be compiled is set back with the rest, and
        // what a broken one said goes with it.
        debounce.stop();
        edits = {};
        live = null;
        said = "";
        marks = {};
        show(path);
    }

    Timer {
        id: debounce
        interval: 500
        onTriggered: page.apply()
    }

    Column {
        width: parent.width
        spacing: Theme.s

        Text {
            width: parent.width
            text: page.demo.title
            color: Theme.text
            font.family: Theme.sans
            font.pixelSize: page.wide ? Theme.displaySize : Theme.compactDisplaySize
            font.weight: Font.Bold
            lineHeightMode: Text.FixedHeight
            lineHeight: page.wide ? Theme.displayLine : Theme.compactDisplayLine
            wrapMode: Text.Wrap
            readonly property int headingLevel: 1
            Accessible.role: Accessible.Heading
        }
        Text {
            width: Math.min(parent.width, Theme.measure)
            text: page.demo.summary
            color: Theme.textMuted
            font.family: Theme.sans
            font.pixelSize: Theme.subtitleSize - 1
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.subtitleLine - 2
            wrapMode: Text.Wrap
        }
    }

    DemoFrame {
        width: parent.width
        scroller: page.scroller
        needs: page.demo.needs
        route: page.demo.route
        // A demo laid out for a tall frame too (`compact`) has that shape
        // where the page is narrow.
        aspect: !page.wide && page.demo.compact ? page.demo.compact.height / page.demo.compact.width : page.demo.height / page.demo.width
        // In the scheme the demo is drawn in, and in the frame's shape
        // (nav.js proPicture).
        picture: Nav.proPicture(page.demo, Theme.picked, Theme.dark, !page.wide)
        what: page.demo.what
        description: page.demo.shows
        demo: running
    }
    // The app, with the page's edits given to it as they compile.
    Component {
        id: running
        Item {
            id: host
            property bool active: true
            property bool calm: false
            // The frame waits on what it holds; what it holds is the app.
            readonly property bool ready: app.status === Loader.Ready && app.item !== null && app.item.ready !== false
            // What the Observer is on: the app, not this frame round it.
            readonly property var observed: app.item
            Loader {
                id: app
                anchors.fill: parent
                source: Live.app(page.demo.name)
                onLoaded: {
                    item.active = Qt.binding(() => host.active);
                    item.calm = Qt.binding(() => host.calm);
                    item.live = Qt.binding(() => page.live);
                }
            }
        }
    }

    // How to use the app, for a demo whose entry says (`use`).
    Text {
        visible: (page.demo.use ?? "") !== ""
        width: Math.min(parent.width, Theme.measure)
        text: page.demo.use ?? ""
        color: Theme.textMuted
        font.family: Theme.sans
        font.pixelSize: Theme.bodySize
        lineHeightMode: Text.FixedHeight
        lineHeight: Theme.bodyLine
        wrapMode: Text.Wrap
    }

    Column {
        width: parent.width
        spacing: Theme.s

        Text {
            width: parent.width
            text: "Its files"
            color: Theme.text
            font.family: Theme.sans
            font.pixelSize: page.wide ? Theme.titleSize + 1 : Theme.titleSize - 1
            font.weight: Font.Bold
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.titleLine + 4
            readonly property int headingLevel: 2
            Accessible.role: Accessible.Heading
        }
        Text {
            width: Math.min(parent.width, Theme.measure)
            text: page.demo.tryThis
            color: Theme.textMuted
            font.family: Theme.sans
            font.pixelSize: Theme.bodySize
            lineHeightMode: Text.FixedHeight
            lineHeight: Theme.bodyLine
            wrapMode: Text.Wrap
        }

        Flow {
            width: parent.width
            spacing: Theme.xxs
            Accessible.role: Accessible.List
            Accessible.name: "The files of " + page.demo.what

            Repeater {
                model: page.files
                delegate: Rectangle {
                    id: tab
                    required property var modelData
                    readonly property bool chosen: modelData.path === page.path
                    readonly property bool changed: Object.hasOwn(page.edits, modelData.path)
                    width: name.implicitWidth + 2 * Theme.xs
                    height: name.implicitHeight + Theme.xs
                    radius: Theme.radiusSmall
                    color: chosen ? Theme.surfaceSelected : press.containsMouse ? Theme.surfaceHover : Theme.surface
                    border.color: activeFocus ? Theme.focusRing : chosen ? Theme.accent : Theme.border
                    border.width: activeFocus ? 2 : 1
                    activeFocusOnTab: true
                    Accessible.role: Accessible.Button
                    Accessible.name: modelData.path + (changed ? ", changed" : "")
                    Accessible.onPressAction: () => page.show(modelData.path)
                    Keys.onPressed: (event) => {
                        if (event.key === Qt.Key_Return || event.key === Qt.Key_Enter || event.key === Qt.Key_Space) {
                            page.show(tab.modelData.path);
                            event.accepted = true;
                        }
                    }

                    Text {
                        id: name
                        anchors.centerIn: parent
                        text: tab.modelData.path + (tab.changed ? " •" : "")
                        color: tab.chosen ? Theme.text : Theme.textMuted
                        font.family: Theme.mono
                        font.pixelSize: Theme.captionSize
                    }
                    MouseArea {
                        id: press
                        anchors.fill: parent
                        hoverEnabled: true
                        Accessible.ignored: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: page.show(tab.modelData.path)
                    }
                }
            }
        }

        Rectangle {
            width: parent.width
            height: head.implicitHeight + Theme.xs
            color: Theme.panel
            border.color: Theme.border
            border.width: 1

            Row {
                id: head
                anchors.left: parent.left
                anchors.leftMargin: Theme.s
                anchors.verticalCenter: parent.verticalCenter
                spacing: Theme.m

                Text {
                    anchors.verticalCenter: parent.verticalCenter
                    text: page.path
                    color: Theme.muted
                    font.family: Theme.mono
                    font.pixelSize: Theme.captionSize
                }
                Text {
                    anchors.verticalCenter: parent.verticalCenter
                    visible: Object.keys(page.edits).length > 0
                    text: "Reset every file"
                    color: Theme.link
                    font.family: Theme.sans
                    font.pixelSize: Theme.captionSize
                    activeFocusOnTab: visible
                    Accessible.role: Accessible.Button
                    Accessible.name: text
                    Accessible.onPressAction: () => page.reset()
                    Keys.onPressed: (event) => {
                        if (event.key === Qt.Key_Return || event.key === Qt.Key_Enter || event.key === Qt.Key_Space) {
                            page.reset();
                            event.accepted = true;
                        }
                    }
                    MouseArea {
                        anchors.fill: parent
                        Accessible.ignored: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: page.reset()
                    }
                }
                Text {
                    anchors.verticalCenter: parent.verticalCenter
                    text: "<a href=\"" + page.sourceBase + page.path + "\" download>Download it</a>"
                    textFormat: Text.RichText
                    linkColor: Theme.link
                    font.family: Theme.sans
                    font.pixelSize: Theme.captionSize
                    onLinkActivated: (link) => Qt.openUrlExternally(link)
                }
            }
        }

        Rectangle {
            width: parent.width
            height: page.wide ? 420 : 320
            color: Theme.codeBg
            border.color: editor.activeFocus ? Theme.focusRing : Theme.border
            border.width: editor.activeFocus ? 2 : 1

            Flickable {
                anchors.fill: parent
                anchors.margins: Theme.s
                contentWidth: editor.width
                contentHeight: editor.height
                clip: true

                CodeEditor {
                    id: editor
                    width: Math.max(parent.width, implicitWidth)
                    code: page.file ? page.file.code : ""
                    rich: page.file && !Object.hasOwn(page.edits, page.path) ? page.file.rich : ""
                    lang: page.file ? page.file.lang : "qml"
                    label: "Edit " + page.path + " of " + page.demo.what
                    errors: told
                    onTextChanged: page.edited(text)
                }
            }
        }

        Text {
            id: told
            visible: page.said !== ""
            width: parent.width
            text: page.said
            color: Theme.danger
            font.family: Theme.mono
            font.pixelSize: Theme.captionSize
            wrapMode: Text.Wrap
        }
    }
}
